1304:     shell.life -= dt;
1305:     shell.x += shell.vx * dt;
1306:     shell.y += shell.vy * dt;
1307:     shell.vx *= Math.exp(-dt * 2.4);
1308:     shell.vy *= Math.exp(-dt * 2.4);
1309:     shell.rot += shell.spin * dt;
1310:     if (shell.life <= 0) shells.splice(i, 1);
1311:   }
