1314: function damageZombie(zombie, damage, angle) {
1315:   if (zombie.dead) return;
1316:   zombie.hp -= damage;
1317:   zombie.hitFlash = 1;
1318:   const force = zombie.type === "brute" ? 32 : 78;
1319:   zombie.knockX += Math.cos(angle) * force;
1320:   zombie.knockY += Math.sin(angle) * force;
1321:   const headX = zombie.x + Math.cos(zombie.angle) * zombie.r * 0.35;
1322:   const headY = zombie.y + Math.sin(zombie.angle) * zombie.r * 0.35;
1323:   bloodBurst(headX, headY, zombie.type === "brute" ? 7 : 4, 0.9);
1324:   sound.hit();
1325:   if (zombie.hp <= 0) killZombie(zombie, angle);
1326: }
