1328: function killZombie(zombie, angle) {
1329:   if (zombie.dead) return;
1330:   zombie.dead = true;
1331:   game.kills += 1;
1332:   game.combo += 1;
1333:   game.comboT = 3;
1334:   const multiplier = 1 + Math.min(4, Math.floor((game.combo - 1) / 4));
1335:   const gained = zombie.score * multiplier;
1336:   game.score += gained;
1337:   game.shake = Math.min(12, game.shake + (zombie.type === "brute" ? 7 : 2));
1338:   bloodBurst(zombie.x, zombie.y, zombie.type === "brute" ? 30 : 15, zombie.type === "brute" ? 1.6 : 1);
1339:   addBloodDecal(zombie.x, zombie.y, zombie.type === "brute" ? 1.6 : zombie.type === "runner" ? 0.8 : 1.1, zombie.type === "brute" ? 10 : 6);
1340:   addText(zombie.x, zombie.y - zombie.r - 6, `+${gained}`, multiplier > 1 ? "#b7ff3e" : "#e8f1df", multiplier > 1 ? 15 : 12);
1341:   if (multiplier > 1) addText(zombie.x, zombie.y - zombie.r - 22, `x${multiplier}`, "#ffca57", 10);
1342: 
1343:   const dropRoll = Math.random();
1344:   if (zombie.type === "brute" || dropRoll < 0.11) dropPickup(zombie.x, zombie.y, "health");
1345:   else if (dropRoll < 0.2) dropPickup(zombie.x, zombie.y, "ammo");
1346: 
1347:   const direction = angle ?? rand(0, TAU);
1348:   for (let i = 0; i < (zombie.type === "brute" ? 7 : 3); i += 1) {
1349:     spawnParticle({
1350:       type: "chunk",
1351:       x: zombie.x,
1352:       y: zombie.y,
1353:       vx: Math.cos(direction + rand(-1.1, 1.1)) * rand(40, 200),
1354:       vy: Math.sin(direction + rand(-1.1, 1.1)) * rand(40, 200),
1355:       life: rand(0.5, 1.2),
1356:       size: rand(2, 5),
1357:       color: pick(["#4a1111", "#5f1914", "#2d1710"])
1358:     });
1359:   }
1360:   sound.kill();
1361:   updateHud(true);
1362: }
