1374: function updateZombies(dt) {
1375:   const count = enemies.length;
1376:   for (const zombie of enemies) {
1377:     if (zombie.dead) continue;
1378:     zombie.hitFlash = Math.max(0, zombie.hitFlash - dt * 4.5);
1379:     zombie.atkCd = Math.max(0, zombie.atkCd - dt);
1380:     zombie.knockX *= Math.exp(-dt * 7);
1381:     zombie.knockY *= Math.exp(-dt * 7);
1382: 
1383:     const dx = player.x - zombie.x;
1384:     const dy = player.y - zombie.y;
1385:     const distance = Math.hypot(dx, dy) || 1;
1386:     const targetAngle = Math.atan2(dy, dx);
1387:     const turnSpeed = zombie.type === "runner" ? 7 : zombie.type === "brute" ? 3.2 : 4.8;
1388:     zombie.angle = angleLerp(zombie.angle, targetAngle, 1 - Math.exp(-dt * turnSpeed));
1389: 
1390:     const wobbleAmount = zombie.type === "runner" ? 0.22 : zombie.type === "brute" ? 0.08 : 0.14;
1391:     const wobble = Math.sin(game.time * 2.7 + zombie.seed) * wobbleAmount;
1392:     const moveAngle = zombie.angle + wobble;
1393:     const speed = zombie.speed;
1394: 
1395:     let vx = Math.cos(moveAngle) * speed + zombie.knockX;
1396:     let vy = Math.sin(moveAngle) * speed + zombie.knockY;
1397: 
1398:     if (count < 45) {
1399:       for (const other of enemies) {
1400:         if (other === zombie || other.dead) continue;
1401:         const ox = zombie.x - other.x;
1402:         const oy = zombie.y - other.y;
1403:         const minDistance = zombie.r + other.r;
1404:         const dist2 = ox * ox + oy * oy;
1405:         if (dist2 > 0.01 && dist2 < minDistance * minDistance) {
1406:           const dist = Math.sqrt(dist2);
1407:           const push = (minDistance - dist) / minDistance;
1408:           vx += ox / dist * push * 70;
1409:           vy += oy / dist * push * 70;
1410:         }
1411:       }
1412:     }
1413: 
1414:     zombie.x = clamp(zombie.x + vx * dt, 22, WORLD.w - 22);
1415:     zombie.y = clamp(zombie.y + vy * dt, 22, WORLD.h - 22);
1416: 
1417:     if (distance < zombie.r + player.r && zombie.atkCd <= 0 && player.invuln <= 0) {
1418:       hurtPlayer(zombie);
1419:       zombie.atkCd = 0.9;
1420:     }
1421:   }
1422: }
