1424: function hurtPlayer(zombie) {
1425:   if (!player.alive || player.invuln > 0) return;
1426:   player.hp = Math.max(0, player.hp - zombie.dmg);
1427:   player.invuln = 0.72;
1428:   game.hitFlash = 1;
1429:   game.shake = Math.min(18, game.shake + 12);
1430:   sound.hurt();
1431:   const angle = Math.atan2(player.y - zombie.y, player.x - zombie.x);
1432:   player.x = clamp(player.x + Math.cos(angle) * 20, 25, WORLD.w - 25);
1433:   player.y = clamp(player.y + Math.sin(angle) * 20, 25, WORLD.h - 25);
1434:   bloodBurst(player.x, player.y, 7, 0.8);
1435:   addText(player.x, player.y - 28, `-${zombie.dmg}`, "#ff5a4a", 13);
1436:   addBloodDecal(player.x, player.y, 0.55, 3);
1437:   if (player.hp <= 0) killPlayer(zombie);
1438:   updateHud(true);
1439: }
