1452:     if (dx * dx + dy * dy < (player.r + 18) * (player.r + 18)) {
1453:       if (pickup.type === "health") {
1454:         player.hp = Math.min(player.maxHp, player.hp + 26);
1455:         addText(player.x, player.y - 32, "+26 PV", "#78f57a", 13);
1456:         toast("Trousse de soin récupérée.");
1457:       } else {
1458:         player.ammo = player.mag;
1459:         player.reloading = false;
1460:         player.reloadT = 0;
1461:         addText(player.x, player.y - 32, "CHARGEUR PLEIN", "#ffca57", 12);
1462:         toast("Chargeur récupéré.");
1463:       }
1464:       sound.pickup();
1465:       particles.push({
1466:         type: "ring",
1467:         x: pickup.x,
1468:         y: pickup.y,
1469:         vx: 0,
1470:         vy: 0,
1471:         life: 0.45,
1472:         maxLife: 0.45,
1473:         size: 8,
1474:         color: pickup.type === "health" ? "#78f57a" : "#ffca57"
1475:       });
1476:       pickups.splice(i, 1);
1477:       updateHud(true);
1478:     }
1479:   }
