1600: function isVisible(x, y, padding = 80) {
1601:   const half = visibleHalf();
1602:   return x > camera.x - half.x - padding
1603:     && x < camera.x + half.x + padding
1604:     && y > camera.y - half.y - padding
1605:     && y < camera.y + half.y + padding;
