1608: function render() {
1609:   const width = view.w;
1610:   const height = view.h;
1611:   ctx.setTransform(view.dpr, 0, 0, view.dpr, 0, 0);
1612:   ctx.fillStyle = "#070b08";
1613:   ctx.fillRect(0, 0, width, height);
1614: 
1615:   const shake = game.shake;
1616:   const shakeX = shake > 0 ? rand(-shake, shake) : 0;
1617:   const shakeY = shake > 0 ? rand(-shake, shake) : 0;
1618: 
1619:   ctx.save();
1620:   ctx.translate(width / 2 + shakeX, height / 2 + shakeY);
1621:   ctx.scale(view.scale, view.scale);
1622:   ctx.translate(-camera.x, -camera.y);
1623: 
1624:   if (!DEBUG.has("noground")) drawGround();
1625:   drawDecals();
1626:   if (!DEBUG.has("nofog")) drawFog();
1627:   drawPickups();
1628:   drawShells();
1629:   drawBullets();
1630: 
1631:   if (game.mode === "menu") {
1632:     for (const zombie of attractZombies) drawZombie(zombie);
1633:     drawPlayer(attractPlayer, false);
1634:   } else {
1635:     for (const zombie of enemies) {
1636:       if (!zombie.dead) drawZombie(zombie);
1637:     }
1638:     drawPlayer(player, true);
