1640: 
1641:   drawParticles();
1642:   drawTexts();
1643:   if (game.mode === "playing" || game.mode === "dying") drawReticle();
1644:   ctx.restore();
1645: 
1646:   if (!DEBUG.has("noeffects")) drawScreenEffects(width, height);
