function updatePowerHud(force = false) {
  const key = `${game.mode}|${POWER_ORDER.map((id) => `${id}:${player.powerCd[id].toFixed(1)}`).join("|")}|${Math.ceil(player.overdrive)}|${Math.ceil(player.adrenaline)}`;
